package br.ufsc.epibuilder.converter;

import br.ufsc.epibuilder.exceptions.InputException;

import java.io.File;
import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.Scanner;

/**
 *
 * @author renato
 */
public class CSVConverter {


    /**
     * Parses a CSV file containing residue-level B-cell epitope prediction
     * scores generated by BepiPred 3.0 or compatible prediction tools.
     *
     * The input CSV must contain four columns in the following order:
     * Accession, Residue, Score, Linear Epitope Score.
     *
     * The Residue column must contain single-letter amino acid codes.
     * Each row represents an individual amino acid residue associated
     * with a protein accession identifier. Residues are grouped by
     * accession to reconstruct protein sequences and their corresponding
     * epitope prediction scores.
     *
     * Expected CSV format:
     * Accession,Residue,Score,Linear Epitope Score
     *
     * @param csvFile the input CSV file containing residue-level epitope
     *                prediction scores
     * @return an ArrayList of ProteinConverter objects containing the
     *         reconstructed protein sequences and associated scores
     * @throws FileNotFoundException if the specified CSV file does not exist
     * @throws InputException if the CSV file contains invalid or
     *                        improperly formatted input data
     */
    public static ArrayList<ProteinConverter> getProteinFromCSV(File csvFile) throws FileNotFoundException, InputException {
        ArrayList<ProteinConverter> proteins = new ArrayList<>();
        try (Scanner s = new Scanner(csvFile)) {
            ProteinConverter protein = new ProteinConverter("");
            s.nextLine();
            while (s.hasNext()) {
                try {
                    String val = s.nextLine();

                    String[] fields = val.split(",");
                    String id = fields[0];
                    String aa = fields[1].toUpperCase();
                    //Using BepiPred-3.0 linear epitope score
                    double score = Double.parseDouble(fields[3]);

                    if (!protein.getId().equals(id)) {
                        protein = new ProteinConverter(id);
                        proteins.add(protein);
                    }
                    protein.addAmino(aa, score);

                } catch (Exception e) {
                    e.printStackTrace();
                    throw new InputException(e);
                }

            }
        }
        return proteins;
    }

    /**
     * Parses a tab-separated file containing residue-level B-cell epitope
     * prediction scores generated by EpiDope.
     *
     * The first line is a header and is skipped. Each protein starts with a
     * line beginning with {@code >} followed by its identifier, and is
     * followed by one line per residue with three tab-separated columns:
     * position, amino acid and score. Blank lines and repeated header lines
     * are ignored.
     *
     * Expected format:
     * <pre>
     * position/header    aminoacid    score
     * &gt;P18272
     * 1    M    0.6436040997505188
     * 2    D    0.63881915807724
     * </pre>
     *
     * @param csvFile the EpiDope output file containing residue-level
     *                epitope prediction scores
     * @return an ArrayList of ProteinConverter objects containing the
     *         reconstructed protein sequences and associated scores
     * @throws FileNotFoundException if the specified file does not exist
     * @throws InputException if the file contains invalid or improperly
     *                        formatted input data
     */
    public static ArrayList<ProteinConverter> getProteinFromEpidopeCSV(File csvFile) throws FileNotFoundException, InputException {
        ArrayList<ProteinConverter> proteins = new ArrayList<>();
        try (Scanner s = new Scanner(csvFile)) {
            ProteinConverter protein = new ProteinConverter("");
            s.nextLine();
            while (s.hasNext()) {
                try {
                    String line = s.nextLine().trim();
                    if(line.isEmpty() || line.startsWith("position/header")){
                        continue;
                    }

                    if(line.startsWith(">")){
                        protein = new ProteinConverter(line.substring(1));
                        proteins.add(protein);
                        continue;
                    }
                    String[] fields = line.split("\t");

                    String aa = fields[1].toUpperCase();
                    //Using Epidope score
                    double score = Double.parseDouble(fields[2]);

                    protein.addAmino(aa, score);

                } catch (Exception e) {
                    e.printStackTrace();
                    throw new InputException(e);
                }
            }
        }
        return proteins;
    }
}
